def login(payload: LoginIn, response: Response, db: Db, request: Request):
    user = db.scalar(select(User).where(User.email == payload.email))
    if not user or not pwd.verify(payload.password, user.password_hash) or user.disabled:
        raise HTTPException(401, "Invalid credentials")

def password_reset(email: EmailStr, db: Db):
    user = db.scalar(select(User).where(User.email == email))
    if user:
        user.reset_token = secrets.token_urlsafe(24)
        db.commit()
    return {"message": "If the account exists, a local reset token was generated.", "reset_token": user.reset_token if user else None}

def register(payload: RegisterIn, response: Response, db: Db, request: Request):
    if db.scalar(select(User).where(User.email == payload.email)):
        raise HTTPException(409, "Email already registered")
    user = User(email=payload.email, full_name=payload.full_name, role=Role.borrower, password_hash=pwd.hash(payload.password))

def logout(response: Response):
    response.delete_cookie("lp_session")
    return {"ok": True}

def get_application(app_id: int, user: CurrentUser, db: Db, request: Request):
    app_obj = load_app(db, user, app_id, request)
    db.commit()
    return app_detail(app_obj, user)
